 {auto g=fixture();g.hero.skills[Necromancy]=1;BattleReport r;r.won=true;g.resolveBattleSkills(r,casualties(Pikeman,1,1));check(r.raised.count==1,"Necromancy minimum one creature missing");g.hero.wornArtifacts={54,55,56};check(g.necromancyRate(g.hero,0)==40,"Necromancy artifact bonuses missing");}
 for(int mastery=1;mastery<=3;++mastery){auto g=fixture();g.hero.skills[EagleEye]=mastery;g.hero.skills[Wisdom]=3;g.randomState=1;BattleReport r;r.won=true;Battle b;b.spellHistory[1][MagicArrow]=true;b.spellHistory[1][Resurrection]=true;b.spellHistory[1][Implosion]=true;b.spellHistory[1][TownPortal]=true;g.resolveBattleSkills(r,b);check(g.hero.spells[MagicArrow],"Eagle Eye did not learn observed successful spell");check(!g.hero.spells[Implosion]&&!g.hero.spells[TownPortal],"Eagle Eye learned fifth-level or adventure spell");if(mastery<3)check(!g.hero.spells[Resurrection],"Eagle Eye ignored mastery ceiling");}
 {auto g=fixture();g.hero.skills[EagleEye]=3;g.hero.skills[Wisdom]=0;g.randomState=1;Battle b;b.spellHistory[1][Resurrection]=true;BattleReport r;r.won=true;g.resolveBattleSkills(r,b);check(!g.hero.spells[Resurrection],"Eagle Eye ignored Wisdom ceiling");g.hero.spells[MagicArrow]=true;g.startBattle(15);auto enemy=g.battle->units.back();check(g.cast(MagicArrow,{enemy.x,enemy.y}).empty()&&g.battle->spellHistory[0][MagicArrow],"Actual spell cast was not recorded");}
 {auto g=fixture();g.hero.skills[Tactics]=1;g.startBattle(15);check(g.battle->tacticsTeam==0&&g.battle->tacticsRange==3,"Basic Tactics did not open three-column deployment");check(g.act("move",{2,5}).empty(),"Tactics did not reposition selected stack");auto before=g.toJson();check(!g.act("move",{4,5}).empty()&&g.toJson()==before,"Tactics crossed deployment limit");check(!g.act("attack",{14,5}).empty(),"Tactics allowed attacks before combat");g.hero.spells[MagicArrow]=true;int mana=g.hero.mana;check(!g.cast(MagicArrow,{14,5}).empty()&&g.hero.mana==mana,"Tactics allowed spell payment");check(g.act("end-tactics").empty()&&g.battle->tacticsTeam<0&&g.battle->round==1,"Ending tactics spent a combat round");}
