 {auto g=fixture();g.objectById(15)->properties={{"disposition",0},{"never_flees",0}};g.encounterMonster(15);check(g.neutralOffer&&g.neutralOffer->intent==NeutralIntent::JoinFree&&!g.battle,"Compliant creatures did not offer joining");int n=armyCount(g.hero.army);g.answerNeutral(true);check(!g.objectById(15)&&armyCount(g.hero.army)==n+8,"Free joining did not merge army and remove monster");}
