 {auto g=fixture();g.objectById(15)->properties={{"disposition",0}};g.encounterMonster(15);auto p=std::filesystem::temp_directory_path()/"h3-secondary-skills.json";std::string error;check(g.save(p,error),error.c_str());Game restored;check(restored.load(p,error)&&restored.toJson()==g.toJson(),"Pending diplomacy did not round-trip");std::filesystem::remove(p);}

 for(int own=0;own<=3;++own)for(int foe=0;foe<=3;++foe){auto g=fixture();g.hero.skills[Tactics]=own;auto*o=g.objectById(15);o->type=ObjectType::EnemyHero;Hero other;other.army=o->army;other.skills[Tactics]=foe;g.heroes[15]={other,1,0};g.startBattle(15);if(own>foe)check(g.battle->tacticsTeam==0&&g.battle->tacticsRange==2*(own-foe)+1,"Tactics level difference wrong");else check(g.battle->tacticsTeam==-1,"Equal or automated enemy tactics did not finish");}
 {auto g=fixture();g.hero.skills[Tactics]=3;g.startBattle(15);auto before=g.toJson();check(!g.tacticsMove(0,{0,5})&&g.toJson()==before,"Two-hex deployment crossed board edge");auto path=std::filesystem::temp_directory_path()/"h3-tactics-save.json";std::string e;check(g.save(path,e),e.c_str());Game loaded;check(loaded.load(path,e)&&loaded.toJson()==before,"Tactics phase failed roundtrip");std::filesystem::remove(path);}
 {Hero h;heroDefaults(h,69);check(h.skills[Necromancy]>0&&secondarySpecialty(69)==Necromancy,"Isra starting skill or specialty missing");auto g=fixture();h.level=1;h.skills[Necromancy]=1;check(g.necromancyBasisPoints(h,0)==1050,"Necromancy specialty lost fractional percent");h.level=20;check(g.necromancyBasisPoints(h,0)==2000,"Necromancy specialty is not five percent per level");}
 {auto g=fixture();g.hero.skills[EagleEye]=1;int learned=0;for(int seed=1;seed<=4000;++seed){auto trial=g;trial.randomState=uint32_t(seed)*2654435761u;Battle b;b.spellHistory[1][MagicArrow]=true;BattleReport report;report.won=true;trial.resolveBattleSkills(report,b);learned+=trial.hero.spells[MagicArrow];}check(learned>1500&&learned<1700,"Basic Eagle Eye does not follow forty percent chance");}

 {auto g=fixture();g.hero.skills[Necromancy]=3;g.hero.army={Stack{Pikeman,2},Stack{Archer,2},Stack{Griffin,2},Stack{Swordsman,2},Stack{Monk,2},Stack{Cavalier,2},Stack{Angel,2}};BattleReport r;r.won=true;g.resolveBattleSkills(r,casualties(Pikeman,1,100));check(r.raisedPending&&r.raised.unit==Skeleton&&r.raised.count==30,"Full army silently lost necromancy reward");g.report=r;check(g.answerNecromancy(0).find("已接收")!=std::string::npos&&g.hero.army[0].unit==Skeleton&&g.hero.army[0].count==30&&!g.report->raisedPending,"Choosing a necromancy replacement did not receive units");}
 {auto g=fixture();g.hero.army={Stack{Pikeman,2}};g.hero.spells[MagicArrow]=true;auto*o=g.objectById(15);o->army={Stack{Archangel,100}};o->type=ObjectType::EnemyHero;Hero enemy;heroDefaults(enemy,13);enemy.level=10;enemy.skills[EagleEye]=3;enemy.skills[Wisdom]=3;enemy.army=o->army;enemy.artifactIds=enemy.wornArtifacts={63,64,65};g.heroes[15]={enemy,1,0};g.startBattle(15);g.battle->queue={0,100};auto target=std::find_if(g.battle->units.begin(),g.battle->units.end(),[](auto&u){return u.team==1;});check(g.cast(MagicArrow,{target->x,target->y}).empty(),"Observed player spell failed");int actions=0;while(g.battle&&actions++<100)g.ai();check(g.report&&!g.report->won&&g.heroes[15].value.spells[MagicArrow],"Winning defender did not learn actual opposing cast");}

 {auto g=Game::create();g.hero.army={Stack{Pikeman,10},Stack{Archer,1},Stack{Griffin,1},Stack{Swordsman,1},Stack{Monk,1},Stack{Cavalier,1},Stack{Angel,1}};auto*o=g.objectById(15);o->pos={g.hero.pos.x+1,g.hero.pos.y};o->army={Stack{Archangel,40}};o->properties={{"disposition",0}};g.encounterMonster(15);auto before=g.toJson();g.answerNeutral(true,9);check(g.toJson()==before,"Invalid diplomatic replacement changed army");g.answerNeutral(true,1);check(!g.neutralOffer&&!g.objectById(15)&&g.hero.army[1].unit==Archangel&&g.hero.army[1].count==40,"Full army could not replace a stack to accept joining troops");}
